      'ko':
          '낙관적인 마음이시라니 정말 기쁩니다! 긍정적인 사고방식은 어려움을 극복하고 앞으로의 기회를 보는 데 도움이 될 수 있습니다. 오늘 당신의 낙관적인 전망에 영향을 준 것은 무엇인가요?',
      'ru':
          'Замечательно слышать, что вы настроены оптимистично! Ваш позитивный настрой может помочь вам справиться с трудностями и увидеть возможности впереди. Что способствует вашему оптимистичному взгляду сегодня?',
      'uk':
          'Чудово чути, що ви налаштовані оптимістично! Ваше позитивне мислення може допомогти вам долати труднощі та бачити можливості попереду. Що сприяє вашому оптимістичному погляду на життя сьогодні?',
      'zh_Hans': '很高兴听到你这么乐观！积极的心态能帮助你应对挑战，并发现未来的机遇。今天是什么让你保持乐观的心态呢？',
      'zh_Hant': '很高興聽到你這麼樂觀！積極的心態能幫助你應對挑戰，並發現未來的機會。今天是什麼讓你保持樂觀的心態呢？',
    },
