    'z1uyw4nj': {
      'en':
          'Water can be the way in which we express ourselves and find the way to release tension in the body.\n\nUtilize the Escape Basic Breathing Method to focus in on mindful breathing, or use the sound to take a quick breather. \n\nTap Finish when done!',
      'ar':
          'يمكن للماء أن يكون وسيلتنا للتعبير عن أنفسنا وإيجاد طريقة لتخفيف التوتر في الجسم.\n\nاستخدم طريقة التنفس الأساسية \"إسكيب\" للتركيز على التنفس الواعي، أو استخدم الصوت لأخذ قسط من الراحة.\n\nانقر على \"إنهاء\" عند الانتهاء!',
      'de':
          'Wasser kann uns Ausdruckskraft verleihen und uns helfen, Spannungen im Körper abzubauen.\n\nNutze die Escape Basic Breathing Method, um dich auf achtsames Atmen zu konzentrieren, oder nutze das Geräusch für eine kurze Verschnaufpause.\n\nTippe auf „Fertig“, wenn du fertig bist!',
      'es':
          'El agua puede ser nuestra forma de expresarnos y liberar la tensión corporal.\n\nUtiliza el Método de Respiración Básica Escape para concentrarte en la respiración consciente o usa el sonido para tomar un respiro rápido.\n\n¡Toca \"Finalizar\" cuando termines!',
      'fr':
          'L\'eau peut être un moyen de nous exprimer et de libérer les tensions du corps.\n\nUtilisez la méthode de respiration de base Escape pour vous concentrer sur la respiration consciente, ou utilisez le son pour prendre une pause.\n\nAppuyez sur « Terminer » lorsque vous avez terminé !',
      'it':
          'L\'acqua può essere il mezzo con cui ci esprimiamo e troviamo il modo di allentare la tensione nel corpo.\n\nUtilizza il metodo Escape Basic Breathing per concentrarti sulla respirazione consapevole, oppure usa il suono per fare un respiro veloce.\n\nTocca \"Fine\" al termine!',
      'ja':
          '水は、私たちが自分を表現し、体の緊張を解きほぐす方法を見つける手段になり得ます。\n\nエスケープ・ベーシック・ブリージング・メソッドを使ってマインドフルな呼吸に集中したり、音を使って軽く一息ついたりしてみましょう。\n\n終わったら「完了」をタップしてください！',
      'ko':
          '물은 우리가 자신을 표현하고 몸의 긴장을 풀어주는 방법이 될 수 있습니다.\n\n이스케이프 기본 호흡법을 활용하여 마음챙김 호흡에 집중하거나, 소리를 활용하여 빠르게 숨을 쉬어 보세요.\n\n완료되면 \'완료\'를 누르세요!',
      'ru':
          'Вода может быть способом самовыражения и поиска способа снять напряжение в теле.\n\nИспользуйте метод Escape Basic Breathing, чтобы сосредоточиться на осознанном дыхании, или используйте звук, чтобы сделать быструю передышку.\n\nНажмите Finish, когда закончите!',
      'uk':
          'Вода може бути способом самовираження та зняття напруги в тілі.\n\nВикористовуйте базовий метод дихання «Втеча», щоб зосередитися на усвідомленому диханні, або використовуйте звук, щоб швидко перевести дух.\n\nНатисніть «Завершити», коли закінчите!',
      'zh_Hans':
          '水可以成为我们表达自我、释放身体压力的方式。\n\n运用“逃离”基本呼吸法，专注于正念呼吸，或利用声音快速喘息。\n\n完成后，点击“完成”！',
      'zh_Hant':
          '水可以成為我們表達自我、釋放身體壓力的方式。\n\n運用「逃離」基本呼吸法，專注於正念呼吸，或利用聲音快速喘息。\n\n完成後，點擊“完成”！',
