      'en': 'Make Sure To Breathe',
      'ar': 'تأكد من التنفس',
      'de': 'Achten Sie darauf, zu atmen',
      'es': 'Asegúrate de respirar',
      'fr': 'Assurez-vous de respirer',
      'it': 'Assicurati di respirare',
      'ja': '呼吸を忘れずに',
      'ko': '숨을 쉬는 것을 잊지 마세요',
      'ru': 'Обязательно дышите',
      'uk': 'Обов\'язково дихайте',
      'zh_Hans': '确保呼吸',
      'zh_Hant': '確保呼吸',
    },
    'r0xqp97h': {
      'en':
          'Now take the time to breathe in extremely slow for three slow seconds, bringing the mind and heart to a slower pace. When the heartbeat has slowed, the need to exhale arises. \n\nSwipe for the Next Step!',
      'ar':
          'الآن، خذ وقتك في التنفس ببطء شديد لمدة ثلاث ثوانٍ، مما يُبطئ نبضات قلبك وعقلك. عندما يهدأ نبض قلبك، تشعر بالحاجة إلى الزفير.\n\nمرر للخطوة التالية!',
      'de':
          'Atme nun drei Sekunden lang extrem langsam ein und entspanne so Geist und Herz. Sobald sich der Herzschlag beruhigt hat, entsteht das Bedürfnis auszuatmen.\n\nWischen Sie für den nächsten Schritt!',
      'es':
          'Ahora tómate el tiempo para respirar muy despacio durante tres segundos, llevando la mente y el corazón a un ritmo más lento. Cuando el ritmo cardíaco se haya ralentizado, surgirá la necesidad de exhalar.\n\n¡Desliza para ver el siguiente paso!',
      'fr':
          'Prenez maintenant le temps d\'inspirer très lentement pendant trois secondes, en ralentissant le rythme de votre esprit et de votre cœur. Lorsque le rythme cardiaque ralentit, le besoin d\'expirer se fait sentir.\n\nSwipez pour passer à l\'étape suivante !',
      'it':
          'Ora prenditi il tempo di inspirare molto lentamente per tre secondi, portando la mente e il cuore a un ritmo più lento. Quando il battito cardiaco rallenta, nasce il bisogno di espirare.\n\nScorri per il passaggio successivo!',
      'ja':
          '3秒間、ゆっくりと息を吸い込み、心と心臓の鼓動をゆっくりとしたペースにしましょう。心拍が落ち着くと、息を吐き出す必要性が生まれます。\n\n次のステップへはスワイプ！',
      'ko':
          '이제 3초 동안 아주 천천히 숨을 들이마시며 마음과 심장의 속도를 늦춰보세요. 심장 박동이 느려지면 숨을 내쉬고 싶은 욕구가 생깁니다.\n\n다음 단계로 넘어가려면 스와이프하세요!',
      'ru':
          'Теперь найдите время, чтобы сделать очень медленный вдох в течение трех медленных секунд, замедляя темп ума и сердца. Когда сердцебиение замедлится, возникает необходимость выдохнуть. \n\nПроведите пальцем для следующего шага!',
      'uk':
          'Тепер виділіть час, щоб надзвичайно повільно вдихати протягом трьох секунд, уповільнюючи темп розуму та серця. Коли серцебиття сповільниться, виникне потреба видихнути.\n\nПроведіть пальцем, щоб перейти до наступного кроку!',
      'zh_Hans': '现在，花三秒钟极慢地吸气，让思绪和心跳也慢下来。当心跳慢下来时，呼气的需要就产生了。\n\n滑动查看下一步！',
      'zh_Hant': '現在，花三秒鐘極慢地吸氣，讓思緒和心跳也慢下來。當心跳慢下來時，呼氣的需要就產生了。\n\n滑動查看下一步！',
    },
    'bm1dh7wn': {
      'en': 'Step 3',
      'ar': 'الخطوة 3',
      'de': 'Schritt 3',
      'es': 'Paso 3',
      'fr': 'Étape 3',
      'it': 'Fase 3',
      'ja': 'ステップ3',
      'ko': '3단계',
      'ru': 'Шаг 3',
      'uk': 'Крок 3',
      'zh_Hans': '步骤3',
      'zh_Hant': '步驟3',
    },
    't3n3vi3h': {
      'en': 'Stretch & Let Out Negativity',
      'ar': 'تمدد وأطلق العنان للسلبية',
      'de': 'Dehnen und Negativität rauslassen',
      'es': 'Estírate y deja salir la negatividad',
      'fr': 'Étirez-vous et laissez sortir la négativité',
      'it': 'Allunga e lascia uscire la negatività',
      'ja': 'ストレッチしてネガティブな感情を吐き出そう',
      'ko': '스트레칭과 부정적인 감정의 해소',
      'ru': 'Растянитесь и выпустите негатив',
      'uk': 'Розтягнися та випусти негатив',
      'zh_Hans': '伸展并释放消极情绪',
      'zh_Hant': '伸展並釋放負面情緒',
    },
    'ctebjo9p': {
      'en':
          'For the final step, slowly release your breath, stretch, and repeat until satisfied! When you exhale, you should feel a warm feeling go down your back with a rising sense of uplift. \n\nRefer Back to this Guide for Help on How to begin Yoga!',
      'ar':
          'للخطوة الأخيرة، أطلق أنفاسك ببطء، وتمدد، وكرر حتى تشعر بالرضا! عند الزفير، ستشعر بدفء يسري على ظهرك مع شعور متزايد بالرفع.\n\nارجع إلى هذا الدليل للحصول على مساعدة حول كيفية بدء اليوغا!',
      'de':
          'Atmen Sie im letzten Schritt langsam aus, dehnen Sie sich und wiederholen Sie die Übung, bis Sie zufrieden sind! Beim Ausatmen sollten Sie ein warmes Gefühl im Rücken spüren, das Sie mit einem zunehmenden Gefühl der Erhabenheit verbindet.\n\nHier finden Sie weitere Informationen zum Einstieg in Yoga!',
      'es':
          'Para el paso final, exhala lentamente, estira y repite hasta que estés satisfecho. Al exhalar, deberías sentir una sensación cálida que te recorre la espalda con una creciente sensación de elevación.\n\nConsulta esta guía para obtener ayuda sobre cómo empezar a practicar yoga.',
      'fr':
          'Pour la dernière étape, expirez lentement, étirez-vous et répétez jusqu\'à satisfaction ! À l\'expiration, vous devriez ressentir une sensation de chaleur dans le dos, accompagnée d\'une sensation d\'élévation.\n\nReportez-vous à ce guide pour vous aider à débuter le yoga !',
      'it':
          'Per l\'ultimo passaggio, rilascia lentamente il respiro, allungati e ripeti fino a sentirti soddisfatto! Quando espiri, dovresti sentire una sensazione di calore lungo la schiena, accompagnata da una crescente sensazione di sollevamento.\n\nConsulta questa guida per informazioni su come iniziare a praticare yoga!',
      'ja':
          '最後のステップでは、ゆっくりと息を吐き出し、ストレッチをしながら、満足するまで繰り返しましょう。息を吐くと、背中に温かさが伝わり、高揚感が湧き上がってくるのを感じるはずです。\n\nヨガの始め方については、このガイドをご覧ください。',
      'ko':
          '마지막 단계로, 천천히 숨을 내쉬고 스트레칭을 한 후, 만족할 때까지 반복하세요! 숨을 내쉴 때 따뜻한 느낌이 등을 타고 내려가면서 기분이 좋아지는 것을 느껴야 합니다.\n\n요가 시작 방법에 대한 도움말은 이 가이드를 참조하세요!',
      'ru':
          'Для последнего шага медленно выдохните, потянитесь и повторяйте до тех пор, пока не будете удовлетворены! Когда вы выдыхаете, вы должны почувствовать теплое чувство, спускающееся по спине с растущим чувством подъема. \n\nВернитесь к этому руководству для получения помощи о том, как начать заниматься йогой!',
      'uk':
          'На останньому кроці повільно видихніть, потягніться та повторюйте, доки не відчуєте задоволення! Коли ви видихаєте, ви повинні відчути тепло, що проходить по спині, з наростаючим відчуттям піднесення.\n\nЗверніться до цього посібника, щоб отримати допомогу щодо того, як розпочати йогу!',
      'zh_Hans':
          '最后一步，慢慢呼气，伸展身体，重复练习，直到满意为止！呼气时，你会感到一股暖流顺着背部流淌，同时背部也随之升腾。\n\n请参阅本指南，了解如何开始瑜伽！',
      'zh_Hant':
          '最後一步，慢慢吐氣，伸展身體，重複練習，直到滿意為止！呼氣時，你會感覺到一股暖流順著背部流淌，同時背部也隨之升騰。\n\n請參閱本指南，了解如何開始瑜珈！',
    },
  },
