          'تخلص من نقص الطاقة بزيادة الشغف خلال يومك! باستخدام هذه التقنية، يمكنك أن تبدأ يومك بحماس داخلي لتمييز المشاعر.',
      'de':
          'Beseitigen Sie Energiemangel und steigern Sie die Leidenschaft in Ihrem Tag!\nMit dieser Technik können Sie Ihren Tag mit einem inneren Feuer für emotionale Unterscheidungsfähigkeit beginnen.',
      'es':
          '¡Elimina la falta de energía aumentando la pasión en tu día!\nCon esta técnica, puedes comenzar el día con un fuego interior para el discernimiento emocional.',
      'fr':
          'Éliminez le manque d\'énergie en augmentant votre passion au quotidien !\n\nGrâce à cette technique, vous pouvez commencer votre journée avec un feu intérieur propice au discernement émotionnel.',
      'it':
          'Elimina la mancanza di energia con un aumento della passione nella tua giornata!\nCon questa tecnica, puoi iniziare la giornata con un fuoco interiore che ti aiuterà a discernere le tue emozioni.',
      'ja':
          '一日の中で情熱を高め、エネルギー不足を解消しましょう！\nこのテクニックを使えば、感情を洞察するための内なる炎で一日を始めることができます。',
      'ko':
          '하루의 열정을 높여 에너지 부족을 해소하세요!\n이 기법을 사용하면 감정적 분별력을 위한 내면의 불길로 하루를 시작할 수 있습니다.',
      'ru':
          'Устраните недостаток энергии, увеличив страсть в течение дня! Используя эту технику, вы можете начать свой день с внутреннего огня для эмоционального различения.',
      'uk':
          'Позбудьтеся браку енергії, збільшивши свою пристрасть протягом дня! Використовуючи цю техніку, ви можете розпочати свій день із внутрішнім вогнем для емоційного розпізнавання.',
      'zh_Hans': '消除精力不足，提升一天的热情！\n使用这种方法，你可以用内心的热情开启新的一天，洞察情绪。',
      'zh_Hant': '消除精力不足，提升一天的熱情！\n使用這個方法，你可以用內心的熱情開啟新的一天，洞察情緒。',
    },
